package com.bank.lengthgroup;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class GroupByLengthDemo {
    private static final Logger log = Logger.getLogger("LengthGroup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> codes = List.of("SAV2001", "ACC10", "CUR3001", "TXN90", "A");
        LengthGroupService service = new LengthGroupService();

        Map<Integer, List<String>> byLen = service.byLength(codes);
        byLen.forEach((len, list) -> log.info(() -> "len " + len + " → " + list));
    }
}

// ─── Would be in service/LengthGroupService.java ───
class LengthGroupService {
    Map<Integer, List<String>> byLength(List<String> codes) {
        return codes.stream()
            .filter(Objects::nonNull)                 // guard nulls
            .collect(groupingBy(
                String::length,                        // classifier: length
                TreeMap::new,                          // sorted length keys
                toList()));
    }
}
